-- Exam Archive Lifecycle v1 (additive) — see docs/exam-archive-lifecycle-v1.md
-- and prisma/schema.prisma's Exam.archivedAt comment for full field
-- documentation.
--
-- Generated by comparing against:
--   npx prisma migrate diff --from-schema <schema before this change> --to-schema prisma/schema.prisma --script
-- (a genuine schema-to-schema diff, not --from-empty — this project has
-- no prisma/migrations history to diff from-empty against safely, and a
-- direct two-schema diff produces exactly the real delta with no
-- database connection required to generate it).
--
-- Additive only — ONE new nullable column on the existing Exam table.
-- No existing table, column, constraint, row, enum value, or index is
-- changed, removed, or renamed. No new table, no new enum.
--
-- New column: Exam.archivedAt (nullable TIMESTAMP(3)). NULL means "not
-- archived" (the value for every existing row, including all 100+
-- pre-existing exams — this ALTER TABLE never populates it). Non-null
-- means "archived at this timestamp" — a purely lecturer-facing
-- organisational flag, read only by lecturer-scoped list/count queries
-- (GET /api/exams, the lecturer dashboard, course exam lists). No
-- student-facing route reads this column — archiving an exam never
-- changes whether a student can access, join, or submit it. See
-- docs/exam-archive-lifecycle-v1.md, "What archive does NOT do."
--
-- THIS FILE HAS NOT BEEN APPLIED TO ANY SHARED DATABASE. Per
-- docs/migration-ledger.md, Preview and Production currently share ONE
-- Supabase database (project ref ugckdvbjzauvcovcqebw) — this file must
-- be reviewed and applied by an authorized operator via the Supabase SQL
-- Editor (or a direct `pg` client connection using the existing
-- DATABASE_URL), exactly like every other migration in that ledger.
-- It was applied ONLY to a local disposable Postgres database during
-- this feature's own development/test cycle (via `npm run
-- release:validate`, which runs `prisma db push` against a throwaway
-- Docker container that is destroyed immediately after the run) — never
-- against the shared Preview/Production database.

-- Pre-check (read-only) — run this first. Expected: 0 rows (column does
-- not exist yet).
-- SELECT column_name FROM information_schema.columns
-- WHERE table_name = 'Exam' AND column_name = 'archivedAt';

ALTER TABLE "Exam" ADD COLUMN "archivedAt" TIMESTAMP(3);

-- Post-application verification (read-only):
-- 1. Column exists with the right type/nullability:
--    SELECT column_name, data_type, is_nullable FROM information_schema.columns
--    WHERE table_name = 'Exam' AND column_name = 'archivedAt';
--    Expected: data_type = 'timestamp without time zone', is_nullable = 'YES'.
-- 2. No existing row was retroactively archived:
--    SELECT count(*) FROM "Exam" WHERE "archivedAt" IS NOT NULL;
--    Expected: 0, immediately after this ALTER TABLE runs.
-- 3. Exam row count unchanged before/after (this statement only adds a
--    column — it cannot add, remove, or modify rows):
--    SELECT count(*) FROM "Exam";

-- Rollback: safe to drop if this feature must be fully removed —
--   ALTER TABLE "Exam" DROP COLUMN "archivedAt";
-- every application code path already treats a missing/null value as
-- "not archived" (the same as the column's own default state for every
-- existing row), so dropping it only removes the ability to archive
-- going forward — it does not affect any exam, submission, grade,
-- integrity event, or evidence record.
